// ── Camera pin definitions ────────────────────────────────────────────────────
// The ESP32-S3-EYE has different camera wiring than the board variant defaults,
// so we clear the defaults first and set the correct GPIO numbers for this board.
#undef PWDN_GPIO_NUM
#undef RESET_GPIO_NUM
#undef XCLK_GPIO_NUM
#undef SIOD_GPIO_NUM
#undef SIOC_GPIO_NUM
#undef Y9_GPIO_NUM
#undef Y8_GPIO_NUM
#undef Y7_GPIO_NUM
#undef Y6_GPIO_NUM
#undef Y5_GPIO_NUM
#undef Y4_GPIO_NUM
#undef Y3_GPIO_NUM
#undef Y2_GPIO_NUM
#undef VSYNC_GPIO_NUM
#undef HREF_GPIO_NUM
#undef PCLK_GPIO_NUM

#define PWDN_GPIO_NUM  -1  // Power down — not used on this board
#define RESET_GPIO_NUM -1  // Hardware reset — not used on this board
#define XCLK_GPIO_NUM  15  // Clock signal fed into the camera sensor
#define SIOD_GPIO_NUM  4   // SCCB data pin (camera's I2C-like config bus)
#define SIOC_GPIO_NUM  5   // SCCB clock pin
#define Y9_GPIO_NUM    16  // Pixel data bus MSB
#define Y8_GPIO_NUM    17
#define Y7_GPIO_NUM    18
#define Y6_GPIO_NUM    12
#define Y5_GPIO_NUM    10
#define Y4_GPIO_NUM    8
#define Y3_GPIO_NUM    9
#define Y2_GPIO_NUM    11  // Pixel data bus LSB
#define VSYNC_GPIO_NUM 6   // Pulses once per complete frame
#define HREF_GPIO_NUM  7   // Pulses once per row of pixels
#define PCLK_GPIO_NUM  13  // Pixel clock — pulses once per pixel

#define LED_PIN        21  // Yellow alert LED — set HIGH when a hazard is detected

// Debug: when 1, each classified frame is streamed over serial so
// scripts/capture_classified_frames.py can save the exact bitmap the model saw.
// Set to 0 for normal deployment (it adds ~0.8s/frame of serial transfer).
#define DUMP_FRAMES    1

// ── Shared frame buffer pointer ───────────────────────────────────────────────
// loop() sets this to point at the camera frame. The Edge Impulse signal
// callback (get_signal_data) reads from it to feed pixels into the classifier.
static uint8_t *frame_buf_ptr = nullptr;

