// ── Edge Impulse signal callback ──────────────────────────────────────────────
// Edge Impulse doesn't read the image directly — it calls this function to
// pull pixel data in chunks. We convert each raw byte (0–255) to a float
// (0.0–1.0) because that's the format the model was trained on.
static int get_signal_data(size_t offset, size_t length, float *out_ptr) {
    for (size_t i = 0; i < length; i++) {
        uint8_t gray = frame_buf_ptr[offset + i];
        // EI image DSP block is configured for RGB — pack grayscale as R=G=B
        out_ptr[i] = (float)((gray << 16) | (gray << 8) | gray);
    }
    return EIDSP_OK;
}

// ── Setup — runs once on boot ─────────────────────────────────────────────────
void setup() {
    // Start serial at 115200 baud for debug output in the serial monitor
    Serial.begin(115200);

    // Wait up to 5 seconds for a USB serial connection before continuing
    uint32_t t = millis();
    while (!Serial && (millis() - t) < 5000) delay(10);
    delay(1000);

    // Set up the alert LED — starts OFF
    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW);

    Serial.println("=== Hazard Beacon - Inference Mode ===");
    Serial.printf("PSRAM total: %u bytes  free: %u bytes\n",
                  ESP.getPsramSize(), ESP.getFreePsram());

    // ── WiFi (disabled) ───────────────────────────────────────────────────────
    // Uncomment to connect to WiFi and enable Telegram alerts.
    /*
    WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
    Serial.print("Connecting to WiFi");
    uint32_t wifi_start = millis();
    while (WiFi.status() != WL_CONNECTED && (millis() - wifi_start) < 15000) {
        delay(500);
        Serial.print(".");
    }
    if (WiFi.status() == WL_CONNECTED) {
        Serial.printf("\nWiFi connected: %s\n", WiFi.localIP().toString().c_str());
    } else {
        Serial.println("\nWiFi failed — continuing without notifications");
    }
    */

    // ── Camera initialisation ─────────────────────────────────────────────────
    // Configure the OV2640 camera sensor. The resolution (96×96) and pixel
    // format (grayscale) must match what the model was trained on in Edge Impulse.
    camera_config_t config;
    config.ledc_channel = LEDC_CHANNEL_0;      // LEDC peripheral generates the XCLK signal
    config.ledc_timer   = LEDC_TIMER_0;
    config.pin_d0       = Y2_GPIO_NUM;         // 8-bit parallel pixel data bus
    config.pin_d1       = Y3_GPIO_NUM;
    config.pin_d2       = Y4_GPIO_NUM;
    config.pin_d3       = Y5_GPIO_NUM;
    config.pin_d4       = Y6_GPIO_NUM;
    config.pin_d5       = Y7_GPIO_NUM;
    config.pin_d6       = Y8_GPIO_NUM;
    config.pin_d7       = Y9_GPIO_NUM;
    config.pin_xclk     = XCLK_GPIO_NUM;
    config.pin_pclk     = PCLK_GPIO_NUM;
    config.pin_vsync    = VSYNC_GPIO_NUM;
    config.pin_href     = HREF_GPIO_NUM;
    config.pin_sccb_sda = SIOD_GPIO_NUM;
    config.pin_sccb_scl = SIOC_GPIO_NUM;
    config.pin_pwdn     = PWDN_GPIO_NUM;
    config.pin_reset    = RESET_GPIO_NUM;
    config.xclk_freq_hz = 20000000;            // 20 MHz clock to the sensor
    config.pixel_format = PIXFORMAT_GRAYSCALE; // Single channel — matches training data
    config.frame_size   = FRAMESIZE_96X96;     // 96×96 pixels — must match model input size
    config.fb_count     = 2;                   // Two frame buffers so capture and inference can overlap
    config.grab_mode    = CAMERA_GRAB_LATEST;  // Always grab the most recent frame (discard stale ones)

    esp_err_t err = esp_camera_init(&config);
    if (err != ESP_OK) {
        Serial.printf("Camera init FAILED: 0x%x\n", err);
        return;
    }

    // ── Lock exposure / gain (fixed Ring-style scene) ─────────────────────────
    // Sensor settings must be applied AFTER esp_camera_init(). We lock exposure and
    // gain so the background looks identical every frame. This prevents the model
    // from keying on brightness: with auto-exposure ON and a white background, an
    // intruder lowers average brightness, the sensor raises exposure, and background
    // brightness becomes correlated with the class. Locking removes that confound and
    // also stops the dark/bright frame flip. Tune AEC_VALUE once so the empty scene is
    // well-exposed (not clipped white); the same value is used for collect and deploy.
    sensor_t *s = esp_camera_sensor_get();
    if (s) {
        const int AEC_VALUE = 300;      // fixed exposure — tune to your scene/lighting
        const int AGC_GAIN  = 0;        // fixed gain (0 = lowest)
        s->set_exposure_ctrl(s, 0);     // disable auto exposure (AEC)
        s->set_aec2(s, 0);              // disable AEC2 algorithm
        s->set_aec_value(s, AEC_VALUE); // apply fixed exposure
        s->set_gain_ctrl(s, 0);         // disable auto gain (AGC)
        s->set_agc_gain(s, AGC_GAIN);   // apply fixed gain
        s->set_whitebal(s, 0);          // disable auto white-balance drift
        // For nighttime IR later: raise AEC_VALUE / AGC_GAIN and set GAINCEILING_16X.
    }

    Serial.println("Camera initialized (exposure locked). Running inference every 2 seconds...");
}

