// ── NORMAL CAMERA MODE loop ───────────────────────────────────────────────────
// Runs continuously. Each iteration: captures a frame, runs the classifier,
// lights the LED if a hazard is detected, and prints the result to serial.
void loop() {
    // Step 1: Capture a frame from the camera into a DMA buffer
    camera_fb_t *fb = esp_camera_fb_get();
    if (!fb) {
        Serial.println("ERROR: Frame capture failed");
        delay(1000);
        return;
    }

    // Step 2: Point the global frame pointer at the captured pixel data
    frame_buf_ptr = fb->buf;

    // ── Test image mode (disabled) ────────────────────────────────────────────
    // Uncomment to skip the camera and cycle through hardcoded test images instead.
    // Run scripts/image_to_header.py first to generate test_image.h, then comment
    // out the camera block above and uncomment below.
    // static int img_idx = 0;
    // frame_buf_ptr = (uint8_t*)test_images[img_idx];
    // Serial.printf("[Test %d/%d] true label: %s\n", img_idx + 1, test_image_count, test_image_labels[img_idx]);

    // Step 3: Set up the Edge Impulse signal descriptor — tells the SDK how
    // many pixels to expect and which function to call to read them
    signal_t signal;
    signal.total_length = EI_CLASSIFIER_INPUT_WIDTH * EI_CLASSIFIER_INPUT_HEIGHT;
    signal.get_data     = &get_signal_data;

    // Step 4: Run inference
    // esp_task_wdt_reset() feeds the watchdog timer just before the ~4.5s
    // float32 inference call so the device doesn't reset mid-inference.
    ei_impulse_result_t result;

    run_classifier_init();
    esp_task_wdt_reset();
    EI_IMPULSE_ERROR ei_err = run_classifier(&signal, &result, false);

    if (ei_err != EI_IMPULSE_OK) {
        Serial.printf("Classifier error: %d\n", ei_err);
        esp_camera_fb_return(fb);  // still release the buffer on the error path
        return;
    }

    // Step 5: Extract scores for each class from the result
    float hazard_score  = 0;
    float ambient_score = 0;
    for (size_t i = 0; i < EI_CLASSIFIER_LABEL_COUNT; i++) {
        const char* label = result.classification[i].label;
        float  value = result.classification[i].value;

        if (strcmp(label, "hazard_detected") == 0) hazard_score  = value;
        if (strcmp(label, "ambient_noise")  == 0) ambient_score = value;
    }

    // Step 6: Trigger the LED if the hazard confidence exceeds 60%
    bool hazard_detected = hazard_score > 0.6f;
    digitalWrite(LED_PIN, hazard_detected ? HIGH : LOW);

    // Step 7: (debug) Stream the exact frame the classifier just saw over serial,
    // tagged with the decision and both scores. scripts/capture_classified_frames.py
    // reads this and saves it as a PNG so you can inspect what produced each result.
    // Done before esp_camera_fb_return so fb->buf is still valid.
#if DUMP_FRAMES
    Serial.printf("FRAME_START:%u:%s:%.4f:%.4f\n",
        (unsigned)fb->len,
        hazard_detected ? "hazard" : "clear",
        hazard_score, ambient_score);
    Serial.write(fb->buf, fb->len);
    Serial.println();
#endif

    // Release the camera frame buffer now that we're done with the pixels
    esp_camera_fb_return(fb);

    // Step 8: Send a Telegram alert (disabled — uncomment with WiFi to re-enable)
    // if (millis() - last_alert_ms > ALERT_COOLDOWN_MS) {
    //     sendTelegramAlert(hazard_score);
    //     last_alert_ms = millis();
    // }

    // Step 9: Print result to serial monitor
    Serial.printf("[Inference] hazard=%.8f  ambient=%.8f  → %s\n",
        hazard_score, ambient_score,
        hazard_detected ? "HAZARD DETECTED" : "clear");
}
